/* ===== Dù lượn nhiều người: nội suy vị trí dù người khác (thuần, không import) =====
   Vòng đệm cố định 8 mẫu (t, x, y, z, yaw, bank), nội suy tuyến tính, yaw đi đường ngắn qua ±π, kẹp ở mẫu cuối. Không cấp phát khi push/sample (D-018).
   Mẫu đặt theo giờ của người gửi (e[6]) quy ra giờ khách, nên trễ mạng và việc máy chủ gộp gói không làm dù đứng rồi vọt. */
const N = 8, W = 6;   // số mẫu tối đa; số trường mỗi mẫu
export interface ExPose { x: number; y: number; z: number; yaw: number; bank: number }
export interface ExClockParams { clockRelax: number; clockSlewMs: number; clockWarmup: number }   // xem multiParams

export class ExTrack {
  private buf = new Float64Array(N * W);
  private head = 0;      // chỉ số ô sẽ ghi tiếp
  private n = 0;         // số mẫu đang có
  private off = NaN;     // độ lệch giờ người gửi → giờ khách (ms); NaN = chưa có mẫu nào có giờ
  private fed = 0;       // số mẫu có giờ đã nhận: clockWarmup mẫu đầu lấy thẳng mức nhỏ nhất (gói đầu có thể trễ vì khung hình chậm), sau đó mới giới hạn slew
  get count(): number { return this.n; }

  push(t: number, x: number, y: number, z: number, yaw: number, bank: number): void {
    if (this.n > 0 && t <= this.buf[((this.head + N - 1) % N) * W]) return;   // mẫu cũ hoặc trùng giờ: bỏ để giữ thứ tự
    const o = this.head * W, b = this.buf;
    b[o] = t; b[o + 1] = x; b[o + 2] = y; b[o + 3] = z; b[o + 4] = yaw; b[o + 5] = bank;
    this.head = (this.head + 1) % N;
    if (this.n < N) this.n++;
  }

  /* Một mục của gói pos e = [slot, x, y, z, yaw, bank, giờ gửi?] nhận lúc nowMs.
     Có giờ gửi (máy chủ mới): giờ khách = giờ gửi + độ lệch; độ lệch bám mức nhỏ nhất (gói ít trễ nhất) nhưng sau clockWarmup mẫu đầu mỗi mẫu chỉ giảm tối đa clockSlewMs,
     và nới lên clockRelax phần chênh khi mạng chậm đi: độ lệch đổi chậm nên dù không bị co giãn thời gian.
     Không có (máy chủ cũ phát lại vị trí cũ của mọi slot mỗi gói): đóng dấu giờ nhận, bỏ mục trùng mẫu cuối để dù không đứng chờ */
  feed(e: number[], nowMs: number, k: ExClockParams): void {
    const ts = e[6];
    if (typeof ts === 'number' && Number.isFinite(ts)) {
      const c = nowMs - ts;
      if (this.off !== this.off || (c < this.off && this.fed < k.clockWarmup)) this.off = c;
      else if (c < this.off) this.off -= Math.min(this.off - c, k.clockSlewMs);
      else this.off += (c - this.off) * k.clockRelax;
      this.fed++;
      this.push(ts + this.off, e[1], e[2], e[3], e[4], e[5]);
      return;
    }
    if (this.n > 0) {
      const o = ((this.head + N - 1) % N) * W, b = this.buf;
      if (b[o + 1] === e[1] && b[o + 2] === e[2] && b[o + 3] === e[3] && b[o + 4] === e[4] && b[o + 5] === e[5]) return;
    }
    this.push(nowMs, e[1], e[2], e[3], e[4], e[5]);
  }

  /* Ghi vị trí tại thời điểm t vào out; false nếu chưa có mẫu */
  sample(t: number, out: ExPose): boolean {
    if (this.n === 0) return false;
    const b = this.buf, first = (this.head + N - this.n) % N * W;
    const last = ((this.head + N - 1) % N) * W;
    let a = first, c = first;
    if (t >= b[last]) a = c = last;
    else if (t > b[first]) {
      for (let i = 0; i < this.n - 1; i++) {
        const p = (first + i * W) % (N * W), q = (p + W) % (N * W);
        if (t <= b[q]) { a = p; c = q; break; }
      }
    }
    const k = a === c ? 0 : (t - b[a]) / (b[c] - b[a]);
    out.x = b[a + 1] + (b[c + 1] - b[a + 1]) * k;
    out.y = b[a + 2] + (b[c + 2] - b[a + 2]) * k;
    out.z = b[a + 3] + (b[c + 3] - b[a + 3]) * k;
    let dy = b[c + 4] - b[a + 4];
    dy -= Math.round(dy / (2 * Math.PI)) * 2 * Math.PI;
    out.yaw = b[a + 4] + dy * k;
    out.bank = b[a + 5] + (b[c + 5] - b[a + 5]) * k;
    return true;
  }

  reset(): void { this.n = 0; this.head = 0; this.off = NaN; this.fed = 0; }
}
/* ===== Dù lượn nhiều người: thông số dùng chung khách + máy chủ (không import gì; config.ts import file này) ===== */
export const multiParams = {
  url: 'wss://danang-sky.tuanlv5490.workers.dev/sky', // địa chỉ WebSocket của máy chủ Cloudflare; rỗng = chỉ bay một mình
  slots: 5,              // số chỗ bay cùng lúc (theo thiết kế)
  nameMax: 9,            // số grapheme tối đa của tên hiển thị (ước lượng)
  graphemeCpMax: 10,     // code point tối đa trong một grapheme: đủ cho emoji gia đình có màu da, chặn chồng hàng trăm dấu (ước lượng)
  nameCpMax: 48,         // code point tối đa của cả tên (9 emoji gia đình 5 code point vẫn qua) (ước lượng)
  sendHz: 5,             // lần/s khách gửi vị trí (ước lượng, đo ở giai đoạn đầu)
  broadcastMs: 100,      // ms tối thiểu giữa hai lần máy chủ phát gói vị trí gộp (ước lượng)
  posMaxPerSec: 8,       // gói pos tối đa một kết nối được gửi trong 1 s, quá thì bỏ (ước lượng)
  heartbeatMs: 3000,     // ms giữa hai nhịp sống khi không đổi vị trí (ước lượng)
  slotTimeoutMs: 10000,  // ms không có tin thì máy chủ trả slot (ước lượng)
  sweepMs: 10000,        // ms giữa hai lần máy chủ quét slot hết hạn (ước lượng)
  connectTimeoutMs: 4000, // ms chờ kết nối WebSocket trước khi coi là lỗi (ước lượng)
  idleMs: 60000,         // ms không chạm phím thì hiện hỏi "Bạn còn đó không?" (ước lượng)
  idleWarnMs: 15000,     // ms đếm ngược sau khi hỏi, hết thì trả slot (ước lượng)
  idleTickMs: 500,       // ms giữa hai lần kiểm tra rời máy (setInterval, không dùng rAF để tab ẩn vẫn đếm) (ước lượng)
  maxConns: 200,         // số kết nối đồng thời tối đa của phòng (ước lượng)
  maxMsgBytes: 256,      // độ dài tối đa của một tin nhận từ khách, tính theo đơn vị UTF-16 của chuỗi JSON (không phải byte) (ước lượng)
  interpSends: 2.5,      // độ trễ nội suy, tính theo số chu kỳ gửi (ước lượng)
  spawnSpread: 30,       // m lệch điểm cất cánh theo slot để không chồng nhau (ước lượng)
  labelBelow: 9,         // m đặt nhãn tên bên dưới cánh dù (ước lượng)
  lateMs: 5000,          // ms hiện "chỗ vừa bị giành" ở chế độ xem rồi tự ẩn (ước lượng)
  noticeMs: 8000,        // ms hiện "Mất kết nối" khi bay / "đã nhường chỗ" khi xem rồi tự ẩn (ước lượng)
  pendingMs: 4000,       // ms tối đa khóa nút vào bay khi chờ máy chủ trả lời (ước lượng)
  colors: ['#2f9e6e', '#e8892b', '#a855c7', '#2a8fd6', '#e0c02e'], // màu cánh theo slot (ước lượng)
  bounds: { x0: -2600, x1: 3600, z0: -5600, z1: 2800 }, // m — khung bay, phải bằng CONFIG.explore.bounds (có test kiểm)
  floor: 7,              // m — độ cao tối thiểu, phải bằng CONFIG.explore.floor
  ceiling: 800,          // m — độ cao tối đa, phải bằng CONFIG.explore.ceiling
  bankMax: 0.45,         // rad — góc nghiêng tối đa, phải bằng CONFIG.explore.bankMax (máy chủ kẹp bank nhận được)
  clockRelax: 0.01,      // phần chênh được nhận thêm mỗi mẫu khi độ lệch giờ người gửi → giờ khách tăng (mạng chậm đi), không đơn vị (ước lượng)
  clockWarmup: 4,        // số mẫu đầu của một người được nhận thẳng độ lệch nhỏ nhất (gói đầu có thể trễ vì khung hình chậm), ≈ 0,8 s ở 5 lần/s (ước lượng)
  clockSlewMs: 4         // ms tối đa độ lệch giờ người gửi → giờ khách được giảm mỗi mẫu (gói nhanh hơn tới), giữ dù không vọt (ước lượng)
};
/* ===== Dù lượn nhiều người: định dạng tin khách ⇄ máy chủ (JSON) ===== */
import { multiParams } from './params';

export type ClientMsg =
  | { t: 'join'; name: string }
  | { t: 'pos'; x: number; y: number; z: number; yaw: number; bank: number; ts?: number }   // ts: giờ gửi theo đồng hồ của khách (ms); máy chủ cũ bỏ qua
  | { t: 'hb' }
  | { t: 'leave' };

export interface Flyer { slot: number; name: string }

// f: mỗi phần tử [slot, x, y, z, yaw, bank, giờ gửi (ms)]; chỉ gồm slot có vị trí mới. Giờ gửi = ts của khách, khách cũ không gửi ts thì là giờ máy chủ nhận;
// mỗi slot một trục giờ riêng, khách nhận tự quy đổi. Máy chủ cũ (trước bản sửa giật) gửi 6 phần tử và phát lại vị trí cũ của mọi slot: khách mới nhận được cả hai dạng
export type ServerMsg =
  | { t: 'lobby'; flyers: Flyer[] }
  | { t: 'joined'; slot: number }
  | { t: 'rejected'; why: 'full' | 'name' }
  | { t: 'pos'; f: number[][] }
  | { t: 'released' };

// Ký tự trông như khoảng trống dù thuộc nhóm chữ/ký hiệu (chữ đệm Hangul, chữ nổi trống, nguyên âm ẩn Khmer): không tính là chữ thấy được
const BLANK = /[\u115F\u1160\u3164\uFFA0\u2800\u17B4\u17B5]/gu;
const VISIBLE = /[\p{L}\p{N}\p{S}\p{P}]/u;

/* Bỏ ký tự điều khiển và bidi/định dạng (giữ U+200D để ghép emoji), cắt khoảng trắng.
   null nếu: rỗng; không có chữ/số/ký hiệu/dấu câu nào thấy được; quá nameMax grapheme; một grapheme quá graphemeCpMax code point (chồng dấu); tổng quá nameCpMax code point */
export function exSanitizeName(raw: string): string | null {
  if (typeof raw !== 'string') return null;
  const s = raw.replace(/[\p{Cc}\p{Cf}]/gu, c => (c === '\u200D' ? c : '')).trim();
  if (!s || !VISIBLE.test(s.replace(BLANK, ''))) return null;
  const seg = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
  let n = 0, cps = 0;
  for (const g of seg.segment(s)) {
    let k = 0;
    for (const _ of g.segment) k++;
    cps += k;
    if (++n > multiParams.nameMax || k > multiParams.graphemeCpMax || cps > multiParams.nameCpMax) return null;
  }
  return s;
}
/* ===== Dù lượn nhiều người: dù của người bay cùng =====
   Mỗi slot một dù màu riêng (multiParams.colors[slot]), dựng lần đầu slot có người (sync) rồi tái dùng; hình học dùng chung, vật liệu riêng.
   Vị trí nhận 5 lần/s được nội suy theo giờ gửi của từng người (ExTrack.feed), lấy mẫu chậm interpSends chu kỳ để luôn có hai mẫu kẹp. Slot đổi chủ (đổi tên, hoặc từ trống sang có người)
   thì xóa mẫu cũ và ẩn dù tới khi có mẫu đầu, nên dù người mới không trượt từ chỗ người cũ. Không cấp phát mỗi khung (D-018). */
import * as THREE from 'three';
import { scene } from '../../core/renderer';
import { CONFIG } from '../../config';
import { exBuildGlider, exPlaceGlider } from '../glider';
import type { GliderState } from '../flight';
import { ExTrack, type ExPose } from './interp';
import type { Flyer } from './protocol';

const M = CONFIG.explore.multi;

interface RemoteSlot {
  name: string | null;        // null = slot trống
  group: THREE.Group | null;
  track: ExTrack;
  pose: ExPose;               // đệm lấy mẫu
  state: GliderState;         // trạng thái trả cho exPlaceGlider và slotState
  live: boolean;              // đã có mẫu và đang hiện
}

const slots: RemoteSlot[] = Array.from({ length: M.slots }, () => ({
  name: null, group: null, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
  state: { pos: new THREE.Vector3(), yaw: 0, bank: 0, ret: 0, speed: 0 }, live: false
}));
let me = -1;

function hide(s: RemoteSlot): void {
  s.track.reset(); s.live = false;
  if (s.group) s.group.visible = false;
}

export const exRemotes = {
  /* Danh sách người bay đổi (sảnh, vào, ra): dựng dù cho slot mới, đặt lại slot đổi chủ, ẩn slot trống */
  sync(flyers: Flyer[], mySlot: number): void {
    me = mySlot;
    for (let i = 0; i < slots.length; i++) {
      const s = slots[i];
      let name: string | null = null;
      if (i !== mySlot) for (const f of flyers) if (f.slot === i) { name = f.name; break; }
      if (name === null) { s.name = null; hide(s); continue; }
      if (name !== s.name) {
        s.name = name; hide(s);
        if (!s.group) { s.group = exBuildGlider(M.colors[i % M.colors.length]); s.group.visible = false; s.group.traverse(o => o.layers.set(1)); scene.add(s.group); }   // lớp 1: không vẽ vào phản chiếu nước, giữ draw call ≈ 1 mỗi dù
      }
    }
  },

  /* Gói vị trí gộp: f = [slot, x, y, z, yaw, bank, giờ gửi?]; chỉ nhận slot đã biết chủ và không phải của mình */
  onPos(f: number[][], nowMs: number): void {
    for (const e of f) {
      const i = e[0], s = slots[i];
      if (!s || i === me || s.name === null) continue;
      s.track.feed(e, nowMs, M);
    }
  },

  update(nowMs: number): void {
    const t = nowMs - M.interpSends * 1000 / M.sendHz;
    for (const s of slots) {
      if (s.name === null || !s.group) continue;
      if (!s.track.sample(t, s.pose)) { s.live = false; s.group.visible = false; continue; }
      const p = s.pose;
      s.state.pos.set(p.x, p.y, p.z); s.state.yaw = p.yaw; s.state.bank = p.bank;
      exPlaceGlider(s.group, s.state);
      s.group.visible = s.live = true;
    }
  },

  /* Trạng thái đã nội suy của dù ở slot (cho nhãn tên); null nếu chưa có hoặc slot trống */
  slotState(slot: number): GliderState | null {
    const s = slots[slot];
    return s && s.live ? s.state : null;
  },

  /* Dù và tên của slot (cho nhãn tên và test); null nếu slot trống */
  group(slot: number): THREE.Group | null { const s = slots[slot]; return s && s.name !== null ? s.group : null; },
  name(slot: number): string | null { const s = slots[slot]; return s ? s.name : null; },

  /* Rời phòng: ẩn hết, quên tên (dù đã dựng giữ lại để tái dùng) */
  clear(): void {
    me = -1;
    for (const s of slots) { s.name = null; hide(s); }
  }
};

