test('từ tục vẫn bị chặn', () => {
  for (const n of ['fuck', 'FuCk you', 'Đụ má', 'dit', 'đm', 'v.c.l', 'rape', 'dick', 'big dick', 'shit', 'cac', 'lon', 'buoi', 'LON', 'lồn', 'cặc', 'Thằng lồn', 'buồi', 'bitch', 'xfuckx'])
